import os
import secrets
import hashlib
import base64
import urllib.parse
import requests

class PKCELoginFlow:
    def __init__(self):
        self.AUTH0_DOMAIN = os.environ.get("AUTH0_DOMAIN")
        self.AUTH0_CLIENT_ID = os.environ.get("AUTH0_CLIENT_ID")
        self.REDIRECT_URI = os.environ.get("REDIRECT_URI", "http://localhost:8000/callback")
        if not self.AUTH0_DOMAIN or not self.AUTH0_CLIENT_ID:
            raise ValueError("AUTH0_DOMAIN and AUTH0_CLIENT_ID environment variables must be set.")

        self.code_verifier = self._generate_code_verifier()
        self.code_challenge = self._generate_code_challenge(self.code_verifier)
        self.state = self._generate_state()

    def _generate_code_verifier(self):
        # Generate a high-entropy cryptographically random string as per RFC 7636
        # Min length 43 chars, max length 128 chars.
        # Use URL-safe base64 without padding for compatibility.
        return base64.urlsafe_b64encode(os.urandom(32)).rstrip(b'=').decode('utf-8')

    def _generate_code_challenge(self, code_verifier):
        # S256 code challenge method as per RFC 7636
        s256_hash = hashlib.sha256(code_verifier.encode('utf-8')).digest()
        return base64.urlsafe_b64encode(s256_hash).rstrip(b'=').decode('utf-8')

    def _generate_state(self):
        # Generate a cryptographically random string to protect against CSRF attacks
        return secrets.token_urlsafe(32)

    def get_authorization_url(self):
        """
        Constructs the authorization URL for the Auth0 hosted login page.
        """
        authorize_url = f"https://{self.AUTH0_DOMAIN}/authorize"
        params = {
            "response_type": "code",
            "code_challenge": self.code_challenge,
            "code_challenge_method": "S256",
            "client_id": self.AUTH0_CLIENT_ID,
            "redirect_uri": self.REDIRECT_URI,
            "scope": "openid profile email",
            "state": self.state,
            "audience": f"https://{self.AUTH0_DOMAIN}/api/v2/" # Example for management API, adjust as needed
        }
        return f"{authorize_url}?{urllib.parse.urlencode(params)}"

    def exchange_code_for_token(self, authorization_code, state_from_callback):
        """
        Exchanges the authorization code for an access token and ID token.
        """
        if state_from_callback != self.state:
            raise ValueError("State mismatch. Possible CSRF attack.")

        token_url = f"https://{self.AUTH0_DOMAIN}/oauth/token"
        headers = {'Content-Type': 'application/x-www-form-urlencoded'}
        data = {
            "grant_type": "authorization_code",
            "client_id": self.AUTH0_CLIENT_ID,
            "code_verifier": self.code_verifier,
            "code": authorization_code,
            "redirect_uri": self.REDIRECT_URI,
        }

        response = requests.post(token_url, headers=headers, data=data)
        response.raise_for_status()
        return response.json()

    def get_user_info(self, access_token):
        """
        Fetches user information using the access token.
        """
        userinfo_url = f"https://{self.AUTH0_DOMAIN}/userinfo"
        headers = {
            "Authorization": f"Bearer {access_token}"
        }
        response = requests.get(userinfo_url, headers=headers)
        response.raise_for_status()
        return response.json()
